// Device + surface management. Owns adapter/device acquisition, canvas
// configuration (premultiplied alpha, dpr-capped backing store), and the
// DAY-ONE requirement: device-loss recovery. On mobile, losing the GPU device
// when the tab is backgrounded is ROUTINE, not exceptional — every GPU-side
// resource in the engine is created through an owner that registers a rebuild
// callback here, and on `device.lost` the whole stack is recreated from
// CPU-side state without the game noticing.
//
// Module load is DOM-free (testable in Node): all DOM/GPU access happens
// inside init().

/** GPUBufferUsage / GPUTextureUsage / GPUShaderStage bit constants, spelled out
 * so the module never touches the runtime globals (absent in Node). */
export const BITS = {
  // buffer usage
  MAP_READ: 0x1,
  COPY_SRC: 0x4,
  COPY_DST: 0x8,
  INDIRECT: 0x100,
  VERTEX: 0x20,
  UNIFORM: 0x40,
  STORAGE: 0x80,
  // texture usage
  TEXTURE_BINDING: 0x4,
  RENDER_ATTACHMENT: 0x10,
  // shader stages
  STAGE_VERTEX: 0x1,
  STAGE_FRAGMENT: 0x2,
  STAGE_COMPUTE: 0x4,
} as const;

/**
 * Create a shader module and log any WGSL compile errors to the console —
 * WGSL failures are otherwise SILENT (a pipeline just draws nothing). Every
 * module in the engine goes through this (or replicates it); compute kernels
 * especially, since a broken kernel has no visual symptom at all.
 */
export function shaderModule(device: GPUDevice, code: string, label: string): GPUShaderModule {
  const mod = device.createShaderModule({ code, label });
  void mod.getCompilationInfo().then((info) => {
    for (const m of info.messages) {
      if (m.type === 'error') console.error(`${label} WGSL ${m.lineNum}:${m.linePos} ${m.message}`);
    }
  });
  return mod;
}

export interface GpuOptions {
  /** Cap on devicePixelRatio for the backing store (default 1 — render at CSS
   * pixels; retina cap 2 pays 4× the fragments for sharpness). Edge smoothing
   * comes from MSAA (world3d msaa) far more cheaply than from dpr. */
  dprCap?: number;
  /** Called with any GPU/page error message (uncaptured errors, device loss). */
  onError?: (msg: string) => void;
}

/** The live GPU handles for one canvas, with device-loss recovery built in. */
export class Gpu {
  private rebuildFns = new Set<(device: GPUDevice) => void>();
  private lostForever = false;
  private destroyed = false;
  // Resize is EVENT-driven, not polled: `fit()` only touches the DOM when this
  // flag is set. A ResizeObserver flags it on any CSS-box change (window
  // resize, orientation, fullscreen enter/exit); a matchMedia on the current
  // dpr flags it when the pixel ratio flips (window dragged to another monitor,
  // browser zoom) — those don't change the CSS box, so the observer misses them.
  private dirty = true;
  private ro: ResizeObserver | null = null;
  private dprMql: MediaQueryList | null = null;
  private onDprChange: (() => void) | null = null;

  private constructor(
    public device: GPUDevice,
    readonly context: GPUCanvasContext,
    readonly format: GPUTextureFormat,
    readonly canvas: HTMLCanvasElement,
    private opts: GpuOptions,
  ) {}

  /**
   * Request adapter + device and configure the canvas for premultiplied-alpha
   * presentation. Returns null where WebGPU is absent or the adapter request
   * fails (possible even when navigator.gpu exists — blocklisted GPUs).
   */
  static async init(canvas: HTMLCanvasElement, opts: GpuOptions = {}): Promise<Gpu | null> {
    const gpu = navigator.gpu;
    if (!gpu) return null;
    const adapter = await gpu.requestAdapter({ powerPreference: 'high-performance' });
    if (!adapter) return null;
    const device = await adapter.requestDevice();
    const context = canvas.getContext('webgpu');
    if (!context) return null;
    const format = gpu.getPreferredCanvasFormat();
    const self = new Gpu(device, context, format, canvas, opts);
    self.adopt(device);
    context.configure({ device, format, alphaMode: 'premultiplied' });
    self.fit();
    self.watchSize();
    return self;
  }

  /** Watch the canvas for size / dpr changes (see the `dirty` flag) — the fit
   *  is applied lazily on the next `fit()`, so nothing polls the DOM per frame. */
  private watchSize(): void {
    if (typeof window === 'undefined') return;
    if (typeof ResizeObserver !== 'undefined') {
      this.ro = new ResizeObserver(() => { this.dirty = true; });
      this.ro.observe(this.canvas);
    }
    const armDpr = (): void => {
      const dpr = window.devicePixelRatio || 1;
      this.dprMql = window.matchMedia(`(resolution: ${dpr}dppx)`);
      this.onDprChange = (): void => { this.dirty = true; armDpr(); };
      this.dprMql.addEventListener('change', this.onDprChange, { once: true });
    };
    armDpr();
  }

  /** Force the next `fit()` to re-measure (e.g. after a manual layout change). */
  markDirty(): void {
    this.dirty = true;
  }

  /**
   * Register a callback that recreates an owner's GPU resources from CPU-side
   * state. Fired (in registration order) after a lost device is replaced.
   * Returns an unsubscribe function.
   */
  onRebuild(fn: (device: GPUDevice) => void): () => void {
    this.rebuildFns.add(fn);
    return () => this.rebuildFns.delete(fn);
  }

  /**
   * Size the backing store to the canvas's CSS size × dpr (capped). Called per
   * frame but does NOTHING (not even a DOM read) unless a resize/dpr change has
   * flagged it dirty — so the steady state is a single boolean check.
   */
  fit(): boolean {
    if (!this.dirty) return false;
    this.dirty = false;
    const dpr = Math.min(this.opts.dprCap ?? 1, (typeof window !== 'undefined' && window.devicePixelRatio) || 1);
    // clientWidth can be 0 mid-load (hidden/unsized tab) — fall back to the window.
    const w = Math.max(1, Math.floor((this.canvas.clientWidth || window.innerWidth) * dpr));
    const h = Math.max(1, Math.floor((this.canvas.clientHeight || window.innerHeight) * dpr));
    if (w === this.canvas.width && h === this.canvas.height) return false;
    this.canvas.width = w;
    this.canvas.height = h;
    return true;
  }

  /** True once the device is gone and could not be replaced. */
  get dead(): boolean {
    return this.lostForever;
  }

  /** Tear down: stop watching size, drop rebuild hooks, and destroy the device
   *  (frees every GPU texture/buffer the engine created). Idempotent. */
  destroy(): void {
    if (this.destroyed) return;
    this.destroyed = true;
    this.ro?.disconnect();
    this.ro = null;
    if (this.dprMql && this.onDprChange) this.dprMql.removeEventListener('change', this.onDprChange);
    this.dprMql = null;
    this.onDprChange = null;
    this.rebuildFns.clear();
    try { this.device.destroy(); } catch { /* already gone */ }
  }

  private adopt(device: GPUDevice): void {
    this.device = device;
    device.addEventListener('uncapturederror', (e) => {
      this.opts.onError?.(`WebGPU: ${(e as GPUUncapturedErrorEvent).error?.message ?? 'unknown error'}`);
    });
    void device.lost.then((info) => {
      if (info.reason === 'destroyed') return; // deliberate teardown
      this.opts.onError?.(`WebGPU device lost (${info.reason || 'unknown'}) — rebuilding…`);
      void this.recover();
    });
  }

  private async recover(): Promise<void> {
    if (this.destroyed) return; // torn down mid-flight — don't resurrect
    try {
      const gpu = navigator.gpu;
      const adapter = gpu && (await gpu.requestAdapter({ powerPreference: 'high-performance' }));
      if (!adapter) throw new Error('no adapter');
      const device = await adapter.requestDevice();
      this.adopt(device);
      this.context.configure({ device, format: this.format, alphaMode: 'premultiplied' });
      for (const fn of this.rebuildFns) fn(device);
      this.opts.onError?.('WebGPU device rebuilt.');
    } catch (err) {
      this.lostForever = true;
      this.opts.onError?.(`WebGPU device could not be rebuilt: ${String(err)}`);
    }
  }
}

/**
 * A dev-visible error trap: page errors, unhandled rejections and engine
 * messages append to a fixed overlay. WGSL failures are otherwise SILENT in
 * embedded previews — install this in anything you need to debug visually.
 */
export function installErrorOverlay(): (msg: string) => void {
  if (typeof document === 'undefined') return () => {};
  let box: HTMLDivElement | null = null;
  const show = (msg: string): void => {
    if (!box) {
      box = document.createElement('div');
      box.style.cssText =
        'position:fixed;bottom:10px;left:10px;right:10px;max-height:45vh;overflow:auto;color:#ff8080;font:12px/1.4 monospace;background:rgba(20,0,0,.85);padding:8px 12px;border-radius:6px;white-space:pre-wrap;z-index:20';
      document.body.appendChild(box);
    }
    box.textContent += msg + '\n';
  };
  window.addEventListener('error', (e) => show(String(e.message)));
  window.addEventListener('unhandledrejection', (e) => show(String((e as PromiseRejectionEvent).reason)));
  return show;
}
