// Colour parsing for the draw verbs. The public API takes CSS hex strings
// ('#f80', '#ff8800', '#ff880080'); the batcher wants premultipliable floats.
// Parses are cached — games pass the same literals every frame.

export type Rgba = readonly [number, number, number, number];

const cache = new Map<string, Rgba>();

export const WHITE: Rgba = [1, 1, 1, 1];

/** Parse '#rgb' | '#rrggbb' | '#rrggbbaa' to [r,g,b,a] floats 0..1 (cached). */
export function rgba(hex: string): Rgba {
  let c = cache.get(hex);
  if (c) return c;
  let h = hex.startsWith('#') ? hex.slice(1) : hex;
  if (h.length === 3) h = h[0] + h[0] + h[1] + h[1] + h[2] + h[2];
  const n = parseInt(h.length === 6 ? h + 'ff' : h, 16);
  if (Number.isNaN(n) || (h.length !== 6 && h.length !== 8)) {
    c = WHITE;
  } else {
    c = [((n >>> 24) & 0xff) / 255, ((n >>> 16) & 0xff) / 255, ((n >>> 8) & 0xff) / 255, (n & 0xff) / 255];
  }
  cache.set(hex, c);
  return c;
}
